class node{
    public:
        int val;
        int row;
        int col;
        int length;

        node(int data, int i, int j, int s){
            val=data;
            row=i;
            col=j;
            length=s;
        }
};

class compare{
    public:
        bool operator()(node* a, node* b){
            return a->val > b->val;
        }
};

