public:
    vector<int> smallestRange(vector<vector<int>>& nums) {
        int n=nums.size();
        int mini=INT_MAX;
        int maxi=INT_MIN;
        priority_queue<node*, vector<node*>, compare> pq;

        for(int i=0; i<n; i++){
            int element=nums[i][0];
            pq.push(new node(element, i, 0, nums[i].size()));
            maxi=max(maxi, element);
            mini=min(mini, element);
        }

        int start=mini;
        int end=maxi;

        while(pq.size()>0){
            node* temp=pq.top();
            pq.pop();
            mini=temp->val;

            if(maxi-mini<end-start){
                start=mini;
                end=maxi;
            }

            if(temp->col+1<temp->length){
                maxi=max(maxi, nums[temp->row][temp->col+1]);
                pq.push(new node(nums[temp->row][temp->col+1], temp->row, temp->col+1, temp->length));
            }

            else{
                break;
            }
        }
        return {start, end};
    }
};

class Solution {
    public int[] smallestRange(List<List<Integer>> nums) {
        int minx = 0, miny = Integer.MAX_VALUE;
        for (int i = 0; i < nums.size(); i++) {
            for (int j = 0; j < nums.get(i).size(); j++) {
                for (int k = i; k < nums.size(); k++) {
                    for (int l = (k == i ? j : 0); l < nums.get(k).size(); l++) {
                        int min = Math.min(nums.get(i).get(j), nums.get(k).get(l));
                        int max = Math.max(nums.get(i).get(j), nums.get(k).get(l));
                        int n, m;
                        for (m = 0; m < nums.size(); m++) {
                            for (n = 0; n < nums.get(m).size(); n++) {
                                if (nums.get(m).get(n) >= min && nums.get(m).get(n) <= max)
                                    break;
                            }
                            if (n == nums.get(m).size())
                                break;
                        }
                        if (m == nums.size()) {
                            if (miny - minx > max - min || (miny - minx == max - min && minx > min)) {
                                miny = max;
                                minx = min;
                            }
                        }
                    }
                }
            }
        }
        return new int[] {minx, miny};
    }
}

